16	package org.springframework.samples.petclinic.model;
17	
18	import org.springframework.core.style.ToStringCreator;
19	
20	import jakarta.persistence.*;
21	import jakarta.validation.constraints.Digits;
22	import jakarta.validation.constraints.NotEmpty;
23	import jakarta.validation.constraints.Pattern;
24	
25	import java.time.LocalDate;
26	import java.util.*;
27	
28	/**
29	 * Simple JavaBean domain object representing an owner.
30	 *
31	 * @author Ken Krebs
32	 * @author Juergen Hoeller
33	 * @author Sam Brannen
34	 * @author Michael Isvy
35	 */
36	@Entity
37	@Table(name = "owners")
38	public class Owner extends Person {
39	    @Column(name = "address")
40	    @NotEmpty
41	    private String address;
42	
43	    @Column(name = "city")
44	    @NotEmpty
45	    private String city;
46	
47	    @Column(name = "telephone")
48	    @NotEmpty
49	    @Digits(fraction = 0, integer = 10)
50	    @Pattern(regexp = "^[0-9]{10}$", message = "Phone number must be exactly 10 digits")
51	    private String telephone;
52	
53	    @Column(name = "email")
54	    private String email;
55	
56	    @Column(name = "registration_date")
57	    private LocalDate registrationDate;
58	
59	    @Column(name = "membership_number")
60	    private Integer membershipNumber;
61	
62	    @Column(name = "customer_code")
63	    private String customerCode;
64	
65	    @OneToMany(cascade = CascadeType.ALL, mappedBy = "owner", fetch = FetchType.EAGER)
66	    private Set<Pet> pets;
67	
68	    /**
69	     * Ensures a newly persisted owner has a registration date. When an owner is created without
70	     * one, it defaults to today's date.
71	     */
72	    @PrePersist
73	    protected void onRegister() {
74	        if (this.registrationDate == null) {
75	            this.registrationDate = LocalDate.now();
76	        }
77	    }
78	
79	    public String getAddress() {
80	        return this.address;
81	    }
82	
83	    public void setAddress(String address) {
84	        this.address = address;
85	    }
86	
87	    public String getCity() {
88	        return this.city;
89	    }
90	
91	    public void setCity(String city) {
92	        this.city = city;
93	    }
94	
95	    public String getTelephone() {
96	        return this.telephone;
97	    }
98	
99	    public void setTelephone(String telephone) {
100	        this.telephone = telephone;
101	    }
102	
103	    public String getEmail() {
104	        return this.email;
105	    }
106	
107	    public void setEmail(String email) {
108	        this.email = email;
109	    }
110	
111	    public LocalDate getRegistrationDate() {
112	        return this.registrationDate;
113	    }
114	
115	    public void setRegistrationDate(LocalDate registrationDate) {
116	        this.registrationDate = registrationDate;
117	    }
118	
119	    public Integer getMembershipNumber() {
120	        return this.membershipNumber;
121	    }
122	
123	    public void setMembershipNumber(Integer membershipNumber) {
124	        this.membershipNumber = membershipNumber;
125	    }
126	
127	    public String getCustomerCode() {
128	        return this.customerCode;
129	    }
130	
131	    public void setCustomerCode(String customerCode) {
132	        this.customerCode = customerCode;
133	    }
134	
135	    protected Set<Pet> getPetsInternal() {
136	        if (this.pets == null) {
137	            this.pets = new HashSet<>();
138	        }
139	        return this.pets;
140	    }
141	
142	    protected void setPetsInternal(Set<Pet> pets) {
143	        this.pets = pets;
144	    }
145	
146	    public List<Pet> getPets() {
147	        List<Pet> sortedPets = new ArrayList<>(getPetsInternal());
148	        sortedPets.sort(Comparator.comparing(Pet::getName, String.CASE_INSENSITIVE_ORDER));
149	        return Collections.unmodifiableList(sortedPets);
150	    }
151	
152	    public void setPets(List<Pet> pets) {
153	        this.pets = new HashSet<>(pets);
154	    }
155	
156	    public void addPet(Pet pet) {
157	        getPetsInternal().add(pet);
158	        pet.setOwner(this);
159	    }
160	
161	    /**
162	     * Return the Pet with the given name, or null if none found for this Owner.
163	     *
164	     * @param name to test
165	     * @return true if pet name is already in use
166	     */
167	    public Pet getPet(String name) {
168	        return getPet(name, false);
169	    }
170	
171	    /**
172	     * Return the Pet with the given name, or null if none found for this Owner.
173	     *
174	     * @param name to test
175	     * @return true if pet name is already in use
176	     */
177	    public Pet getPet(String name, boolean ignoreNew) {
178	        name = name.toLowerCase();
179	        for (Pet pet : getPetsInternal()) {
180	            if (!ignoreNew || !pet.isNew()) {
181	                String compName = pet.getName();
182	                compName = compName.toLowerCase();
183	                if (compName.equals(name)) {
184	                    return pet;
185	                }
186	            }
187	        }
188	        return null;
189	    }
190	
191	    public Pet getPet(Integer petId) {
192	        return getPetsInternal().stream().filter(p -> p.getId().equals(petId)).findFirst().orElse(null);
193	    }
194	
195	    @Override
196	    public String toString() {
197	        return new ToStringCreator(this)
198	
199	            .append("id", this.getId())
200	            .append("new", this.isNew())
201	            .append("lastName", this.getLastName())
202	            .append("firstName", this.getFirstName())
203	            .append("address", this.address)
204	            .append("city", this.city)
205	            .append("telephone", this.telephone)
206	            .toString();
207	    }
208	}
