17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.util.Collection;
20	import java.util.List;
21	import java.util.Locale;
22	import java.util.Objects;
23	
24	import org.springframework.http.HttpHeaders;
25	import org.springframework.http.HttpStatus;
26	import org.springframework.http.ResponseEntity;
27	import org.springframework.samples.petclinic.mapper.OwnerMapper;
28	import org.springframework.samples.petclinic.mapper.PetMapper;
29	import org.springframework.samples.petclinic.mapper.VisitMapper;
30	import org.springframework.samples.petclinic.model.Owner;
31	import org.springframework.samples.petclinic.model.Pet;
32	import org.springframework.samples.petclinic.model.Visit;
33	import org.springframework.samples.petclinic.rest.api.OwnersApi;
34	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
35	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
36	import org.springframework.samples.petclinic.rest.dto.PetDto;
37	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
38	import org.springframework.samples.petclinic.rest.dto.VisitDto;
39	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
40	import org.springframework.samples.petclinic.service.ClinicService;
41	import org.springframework.security.access.prepost.PreAuthorize;
42	import org.springframework.web.bind.annotation.CrossOrigin;
43	import org.springframework.web.bind.annotation.RequestMapping;
44	import org.springframework.web.bind.annotation.RestController;
45	import org.springframework.web.util.UriComponentsBuilder;
46	
47	import jakarta.transaction.Transactional;
48	
49	/**
50	 * @author Vitaliy Fedoriv
51	 */
52	
53	@RestController
54	@CrossOrigin(exposedHeaders = "errors, content-type")
55	@RequestMapping("/api")
56	public class OwnerRestControllerV1 implements OwnersApi {
57	
58	    private final ClinicService clinicService;
59	
60	    private final OwnerMapper ownerMapper;
61	
62	    private final PetMapper petMapper;
63	
64	    private final VisitMapper visitMapper;
65	
66	    public OwnerRestControllerV1(ClinicService clinicService,
67	                                 OwnerMapper ownerMapper,
68	                                 PetMapper petMapper,
69	                                 VisitMapper visitMapper) {
70	        this.clinicService = clinicService;
71	        this.ownerMapper = ownerMapper;
72	        this.petMapper = petMapper;
73	        this.visitMapper = visitMapper;
74	    }
75	
76	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
77	    @Override
78	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
79	        Collection<Owner> owners;
80	        if (lastName != null) {
81	            owners = this.clinicService.findOwnerByLastName(lastName);
82	        } else {
83	            owners = this.clinicService.findAllOwners();
84	        }
85	        if (owners.isEmpty()) {
86	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
87	        }
88	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
89	    }
90	
91	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
92	    @Override
93	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
94	        Owner owner = this.clinicService.findOwnerById(ownerId);
95	        if (owner == null) {
96	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
97	        }
98	        return new ResponseEntity<>(ownerMapper.toOwnerDto(owner), HttpStatus.OK);
99	    }
100	
101	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
102	    @Override
103	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
104	        HttpHeaders headers = new HttpHeaders();
105	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
106	        owner.setTelephone(normalizeTelephone(owner.getTelephone()));
107	        if (isDuplicateOwner(owner) || isDuplicateEmail(owner)) {
108	            return new ResponseEntity<>(HttpStatus.CONFLICT);
109	        }
110	        owner.setCity(resolveCity(owner.getCity()));
111	        owner.setMembershipNumber(this.clinicService.findAllOwners().size() + 1);
112	        owner.setCustomerCode(nextCustomerCode(owner.getCity()));
113	        this.clinicService.saveOwner(owner);
114	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
115	        headers.setLocation(UriComponentsBuilder.newInstance()
116	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
117	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
118	    }
119	
120	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
121	    @Override
122	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
123	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
124	        if (currentOwner == null) {
125	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
126	        }
127	        currentOwner.setAddress(ownerFieldsDto.getAddress());
128	        currentOwner.setCity(ownerFieldsDto.getCity());
129	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
130	        currentOwner.setLastName(ownerFieldsDto.getLastName());
131	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
132	        this.clinicService.saveOwner(currentOwner);
133	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
134	    }
135	
136	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
137	    @Transactional
138	    @Override
139	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
140	        Owner owner = this.clinicService.findOwnerById(ownerId);
141	        if (owner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        this.clinicService.deleteOwner(owner);
145	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
146	    }
147	
148	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
149	    @Override
150	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
151	        Owner owner = this.clinicService.findOwnerById(ownerId);
152	        if (owner == null) {
153	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
154	        }
155	        HttpHeaders headers = new HttpHeaders();
156	        Pet pet = petMapper.toPet(petFieldsDto);
157	        owner.setId(ownerId);
158	        pet.setOwner(owner);
159	        pet.getType().setName(null);
160	        this.clinicService.savePet(pet);
161	        PetDto petDto = petMapper.toPetDto(pet);
162	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
163	            .buildAndExpand(pet.getId()).toUri());
164	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
165	    }
166	
167	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
168	    @Override
169	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
170	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
171	        if (currentOwner != null) {
172	            Pet currentPet = this.clinicService.findPetById(petId);
173	            if (currentPet != null) {
174	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
175	                currentPet.setName(petFieldsDto.getName());
176	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
177	                this.clinicService.savePet(currentPet);
178	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
179	            }
180	        }
181	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
182	    }
183	
184	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
185	    @Override
186	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
187	        HttpHeaders headers = new HttpHeaders();
188	        Visit visit = visitMapper.toVisit(visitFieldsDto);
189	        Pet pet = new Pet();
190	        pet.setId(petId);
191	        visit.setPet(pet);
192	        this.clinicService.saveVisit(visit);
193	        VisitDto visitDto = visitMapper.toVisitDto(visit);
194	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
195	            .buildAndExpand(visit.getId()).toUri());
196	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
197	    }
198	
199	
200	    /**
201	     * Builds the customer code for a newly created owner, formatted as
202	     * {@code '<UPPERCASE_CITY>-<NNNN>'} where {@code NNNN} is one more than the number of owners
203	     * already registered in that city, zero-padded to four digits (e.g. {@code 'LONDON-0007'}).
204	     *
205	     * @param city the city of the new owner
206	     * @return the assigned customer code
207	     */
208	    private String nextCustomerCode(String city) {
209	        long ownersInCity = this.clinicService.findAllOwners().stream()
210	            .filter(existing -> Objects.equals(
211	                normalize(existing.getCity()), normalize(city)))
212	            .count();
213	        return String.format("%s-%04d", city.toUpperCase(Locale.ROOT), ownersInCity + 1);
214	    }
215	
216	    /**
217	     * Resolves the city to store for a newly created owner. The city is title-cased (so
218	     * {@code "new york"} becomes {@code "New York"}), unless an owner already lives in that
219	     * city, in which case the existing owner's exact spelling of the city name is reused. Cities
220	     * are matched using {@link #normalize(String)}, so the match ignores letter case and any
221	     * surrounding or repeated whitespace.
222	     *
223	     * @param city the city supplied for the new owner, may be {@code null}
224	     * @return the city to store, or {@code null} if the input was {@code null}
225	     */
226	    private String resolveCity(String city) {
227	        if (city == null) {
228	            return null;
229	        }
230	        String normalized = normalize(city);
231	        if (!normalized.isEmpty()) {
232	            for (Owner existing : this.clinicService.findAllOwners()) {
233	                if (normalized.equals(normalize(existing.getCity()))) {
234	                    return existing.getCity();
235	                }
236	            }
237	        }
238	        return toTitleCase(city);
239	    }
240	
241	    /**
242	     * Title-cases free-form text by upper-casing the first letter of each whitespace-separated word
243	     * and lower-casing the remaining letters, preserving the original whitespace. For example
244	     * {@code "new  YORK"} becomes {@code "New  York"}.
245	     *
246	     * @param value the raw value, never {@code null}
247	     * @return the title-cased value
248	     */
249	    private static String toTitleCase(String value) {
250	        StringBuilder result = new StringBuilder(value.length());
251	        boolean startOfWord = true;
252	        for (int i = 0; i < value.length(); i++) {
253	            char c = value.charAt(i);
254	            if (Character.isWhitespace(c)) {
255	                startOfWord = true;
256	                result.append(c);
257	            } else if (startOfWord) {
258	                result.append(Character.toTitleCase(c));
259	                startOfWord = false;
260	            } else {
261	                result.append(Character.toLowerCase(c));
262	            }
263	        }
264	        return result.toString();
265	    }
266	
267	    /**
268	     * Determines whether the given telephone number is already used by any other owner.
269	     *
270	     * @param owner the candidate owner
271	     * @return {@code true} if an owner with the same telephone number already exists in the data store
272	     */
273	    private boolean isDuplicateOwner(Owner owner) {
274	        return this.clinicService.findAllOwners().stream()
275	            .anyMatch(existing -> Objects.equals(existing.getTelephone(), owner.getTelephone()));
276	    }
277	
278	    /**
279	     * Determines whether the given email address is already used by any other owner. An owner
280	     * without an email address is never considered a duplicate on this criterion. Email addresses
281	     * are compared using {@link #normalize(String)} so the check ignores letter case and any
282	     * surrounding or repeated whitespace.
283	     *
284	     * @param owner the candidate owner
285	     * @return {@code true} if the owner provides an email already used by an existing owner
286	     */
287	    private boolean isDuplicateEmail(Owner owner) {
288	        String email = normalize(owner.getEmail());
289	        if (email.isEmpty()) {
290	            return false;
291	        }
